/* ── 图标全家福（新 / 旧）────────────────────────────────────── */

static void sheet_cell(lv_obj_t *p, int x, int y, int icon_kind,
                       const char *name, uint32_t cp, bool old)
{
    lv_obj_t *guide = B(p, x + 15, y, 24, 24, 0x000000u, LV_OPA_TRANSP, 0);

    lv_obj_set_style_border_width(guide, 1, 0);
    lv_obj_set_style_border_color(guide, lv_color_hex(P_HAIR), 0);
    lv_obj_set_style_border_opa(guide, LV_OPA_COVER, 0);
    if (!old) {
        hfi_create(p, (helm_icon_t)icon_kind, x + 27, y + 12, P_INK);
    } else {
        extern void helm_demo_icon(lv_obj_t *p, int kind, int cx, int cy,
                                   uint32_t hex);
        helm_demo_icon(p, icon_kind, x + 27, y + 12, P_INK);
    }
    {
        lv_obj_t *l = LW(p, name, PX_MICRO, P_INK, x, y + 26, 54,
                         LV_TEXT_ALIGN_CENTER);

        (void)l;
    }
    {
        char buf[16];

        if (cp != 0) {
            snprintf(buf, sizeof(buf), "E%03X", (unsigned)cp - 0xE000u);
        } else {
            snprintf(buf, sizeof(buf), "—");
        }
        LW(p, buf, PX_MICRO, P_MUTE, x, y + 39, 54, LV_TEXT_ALIGN_CENTER);
    }
}

static void icons_build(bool old)
{
    static const char *const names[16] = {
        "骑行", "导航", "记录", "设置", "GPS", "电量", "时间", "显示",
        "传感器", "声音", "信息", "右箭头", "返回", "心率", "速度", "海拔",
    };
    const int cols = 4;
    const int cw = 54;
    const int ch = 62;
    const int x0 = 12;
    const int y0 = 44;
    const int n = old ? 11 : 16;

    d_bg(s_scr, P_PAPER);
    if (old) {
        L(s_scr, "图标 · 旧几何占位", PX_BODY, P_INK, 16, 10);
        L(s_scr, "WP-DESIGN4 · 1~2px 混用 · 无统一网格", PX_MICRO, P_MUTE, 16,
          28);
    } else {
        L(s_scr, "图标 · Material Symbols", PX_BODY, P_INK, 16, 10);
        L(s_scr, "20px · 24 网格 · 单色 · 同一字体", PX_MICRO, P_MUTE, 16, 28);
    }
    for (int i = 0; i < n; i++) {
        const int r = i / cols;
        const int c = i % cols;
        /* 旧图标的绘制序号：4 模式 + GPS/电量/时间 + 显示/传感器/声音/信息 */
        static const int old_kind[11] = { 0, 1, 2, 3, 8, 9, 10, 4, 5, 6, 7 };
        const int kind = old ? old_kind[i] : i;

        sheet_cell(s_scr, x0 + c * cw, y0 + r * ch, kind, names[i],
                   old ? 0 : helm_icon_codepoint((helm_icon_t)i), old);
    }
    L(s_scr, old ? "线宽/端点/光学尺寸都不一致" : "线宽/端点/光学尺寸由字体统一",
      PX_MICRO, P_MUTE, 16, 300);
}

