        case 6: { /* 喇叭 */
            lv_point_precise_t sp[7] = {
                { cx - 7, cy - 2 }, { cx - 4, cy - 2 }, { cx + 1, cy - 6 },
                { cx + 1, cy + 6 }, { cx - 4, cy + 2 }, { cx - 7, cy + 2 },

    if (s_phone_pair_s > 0) {
        s_phone_pair_s--;
        if (s_phone_pair_s == 0) {
            s_phone_pair_s = -1;
            toast("配对超时 · 请重试");
            if (s_screen == SCR_BLUETOOTH) {
                rebuild();
            }
        } else if (s_screen == SCR_BLUETOOTH) {
            setl_refresh_values();
        }
    }

    if (s_screen == SCR_SHUTDOWN) {
        if (s_power_phase == 1) {
            s_power_ticks++;
            if (s_power_ticks >= 4) {
                s_power_phase = 2;
                s_power_ticks = 0;
                rebuild();
            } else {
                rebuild();
            }
        } else if (s_power_phase == 2) {
            s_power_ticks++;
            if (s_power_mode == 1 && s_power_ticks >= 3) {
                s_power_phase = 0;
                s_power_ticks = 0;
                s_screen = SCR_DIAL;
                s_busy = false;
                rebuild();
            }
        }
        return;
    }

    if (R.active) {
        const bool was_paused = R.paused;

        ride_advance_1s();
        if (s_screen == SCR_RIDE) {
            if (R.paused != was_paused) {
                rebuild();      /* 自动暂停/自动继续：顶部标签与颜色要换 */
            } else {
                ride_refresh();
            }
#ifdef SIM_WITH_UI
            /* 地图页跟车：底图随里程向东挪（与导航页同一条热路径）。 */
            if (s_ride_page == 2 && s_nav_view != NULL) {
                vmap_view_set_center(s_nav_view,
                                     s_nav_lon + R.dist_km * 0.00004,
                                     s_nav_lat);
            }
#endif
        } else if (s_screen == SCR_NAV) {
            nav_refresh();
#ifdef SIM_WITH_UI
            if (s_nav_view != NULL) {
                vmap_view_set_center(s_nav_view,
                                     s_nav_lon + R.dist_km * 0.00004,
                                     s_nav_lat);
            }
#endif
        } else if (s_screen == SCR_DIAL) {
            if (!LP.active && s_rot_anim == NULL) {
                dial_content(s_mode);
            }
        }
    }

    /* 导航状态机：偏航 → 重规划 → 回到正常；到终点 → 到达横幅。 */
    if (s_nav_active) {
        s_nav_ticks++;
        if (s_nav_phase == 0 && s_nav_ticks >= 45) {
            s_nav_phase = 1;
            s_nav_phase_s = 0;
            toast("偏航 · 正在重新规划");
            if (s_screen == SCR_NAV) {
                rebuild();
            }
        } else if (s_nav_phase == 1) {
            s_nav_phase_s++;
            if (s_reroute && s_nav_phase_s >= 4) {
                s_nav_phase = 0;
                s_nav_turn = (s_nav_turn + 1) % 4;
                s_nav_ticks = 0;
                toast("已重新规划");
                if (s_screen == SCR_NAV) {
                    rebuild();
                }
            } else if (!s_reroute && s_nav_phase_s >= 6) {
                s_nav_phase = 0;
                s_nav_ticks = 0;
                if (s_screen == SCR_NAV) {
                    rebuild();
                }
            }
        }
        if (s_nav_phase != 2 && R.active &&
            (1.6 + R.dist_km) >= 10.0) {
            s_nav_phase = 2;
            toast("已到达终点");
            if (s_screen == SCR_NAV) {
                rebuild();
            }
        }
    }

    if (s_screen == SCR_IDLE) {
        s_idle_s++;
        if (s_idle_dur_l != NULL) {
            char buf[24];

            snprintf(buf, sizeof(buf), "%02d:%02d", s_idle_s / 60,
                     s_idle_s % 60);
            lv_label_set_text(s_idle_dur_l, buf);
        }
        if (s_idle_clock_l != NULL) {
            char buf[24];

            fmt_clock(s_min, buf, sizeof(buf));
            lv_label_set_text(s_idle_clock_l, buf);
        }
        return;
    }

    /* 自动锁定：按键间隔达到设置值 → 熄屏（骑行中仍按表，不熄）。 */
    if (!(R.active && R.speed >= AUTO_PAUSE_ENTER_KMH)) {
        s_idle_s++;
        if (s_lock > 0 && s_idle_s >= s_lock) {
            s_idle_return = s_screen;
            s_idle_s = 0;
            s_screen = SCR_IDLE;
            s_busy = false;
            rebuild();
        }
    } else {
        s_idle_s = 0;
    }
}

