static uint32_t s_tour_frame;
static int s_tour_idx;
static bool s_tour_on;

static void tour_shot(int idx)
{
    int w = 0;
    int h = 0;
    const uint16_t *fb = sim_display_shadow(&w, &h);
    char path[512];

    /* 证据图不带瞬时 toast/长按提示：先清掉，保证十屏是“静态待机”。 */
    s_toast_until = 0;
    hint_clear();

    snprintf(path, sizeof(path), "%s/%s.png", s_tour_dir, TOUR_SHOTS[idx]);
    if (sim_png_write(path, fb, w, h)) {
        printf("helm-tour: shot %s\n", path);
        fflush(stdout);
    } else {
        fprintf(stderr, "helm-tour: failed %s\n", path);
    }
}

static void tour_tick(void)
{
    if (!s_tour_on) {
        return;
    }
    s_tour_frame++;
    while (s_tour_idx < (int)(sizeof(TOUR) / sizeof(TOUR[0])) &&
           TOUR[s_tour_idx].f <= (int)s_tour_frame) {
        const tour_ev_t *e = &TOUR[s_tour_idx];

        s_tour_idx++;
        if (e->kind == 's') {
            tour_shot(e->a);
        } else {
            sim_display_inject_key(e->a, e->b != 0);
        }
    }
    if (s_tour_idx >= (int)(sizeof(TOUR) / sizeof(TOUR[0]))) {
        s_tour_on = false;
    }
}

/* ── 入口 ──────────────────────────────────────────────────────── */

static scr_t screen_from_env(void)
{
    const char *s = getenv("SIM_HELM_SCREEN");

    if (s == NULL || s[0] == '\0' || strcmp(s, "main") == 0) {
        return SCR_DIAL;
    }
    if (strcmp(s, "rotate") == 0 || strcmp(s, "longpress") == 0) {
        return SCR_DIAL;
    }
    for (int i = 0; i < SCR_COUNT; i++) {
        if (strcmp(s, SCR_NAME[i]) == 0) {
            return (scr_t)i;
        }
    }
    fprintf(stderr, "sim: unknown SIM_HELM_SCREEN=%s (main|ride|nav|record|"
                    "settings|display|units|navset|sensor|scan|bluetooth|"
                    "inbox|recset|power|gradecal|usb|about|idle|shutdown|"
                    "routes|navlive|elevation|icons|icons-demo|iconopt)\n", s);
    return SCR_DIAL;
}

