/* ── 长按 / 输入 ────────────────────────────────────────────────
 *
 * 三键统一时序（板端手感阈值，全部按真实按下/抬起时间判定）：
 *   单击  = 按住 <400 ms 松开（松手才触发）
 *   长按  = 按住 ≥800 ms（按住到 800 立刻触发；之后松开不再算单击）
 *   取消  = 400~799 ms 松开（进度回 0，不产生动作）
 *   双击  = 上键两次单击间隔 <300 ms
 */
#define KEY_CLICK_MS 400
#define KEY_LONG_MS  800
#define KEY_DBL_MS   300

typedef enum {
    LP_NONE = 0,
    LP_ENTER,      /* 盘面：进入选中模式 */
    LP_BACK,       /* 骑行/设置：返回（记录继续） */
    LP_ACTIVATE,   /* 设置列表：确定（进入子页 / 循环当前值） */
    LP_PAUSE,      /* 骑行：暂停 / 继续 */
    LP_NAV_CTRL,   /* 导航：本次导航 / 海拔 */
    LP_GRADE_ZERO, /* 坡度校准：归零 */
    LP_TOGGLE_RIDE /* 盘面 KEY2：开始骑行 */
} lp_target_t;

/* 弹窗（模态）：弹窗期间只有弹窗自己的 ←/→ 响应，其它键一律吞掉。 */
typedef enum {
    MODAL_NONE = 0,
    MODAL_SHUTDOWN,   /* 上键长按：确认关机？ 左=取消 右=确认 */
    MODAL_SAVE_ASK,   /* 暂停态右键：保存本次骑行？ 左=不保存 右=保存 */
    MODAL_SAVE_DONE   /* 第二个弹窗：已保存/未保存 · N 次记录；右键关闭 */
} modal_t;

static modal_t s_modal;
static bool s_modal_saved;
static int s_modal_key;
static uint32_t s_modal_t0;

static struct {
    bool active;
    int key;
    uint32_t t0;
    uint32_t dur;
    lp_target_t target;
} LP;

static void keylog(const char *fmt, ...);   /* SIM_HELM_KEYLOG=1 时打印 */

static lv_timer_t *s_ui_timer;
static lv_timer_t *s_data_timer;

/** 设置列表页（KEY1 长 = 激活当前行）。 */
static bool screen_is_setlist(scr_t s)
{
    switch (s) {
        case SCR_SETTINGS:
        case SCR_DISPLAY:
        case SCR_UNITS:
        case SCR_NAV_SET:
        case SCR_SENSOR:
        case SCR_SENSOR_SCAN:
        case SCR_BLUETOOTH:
        case SCR_INBOX:
        case SCR_REC_SET:
        case SCR_POWER:
        case SCR_USB:
        case SCR_ROUTE_SRC:
        case SCR_NAV_LIVE:
            return true;
        default:
            return false;
    }
}

static bool screen_has_lp1(void)
{
    /* 暂停态：左键长按无动作（表里是 “—”）。 */
    if (s_screen == SCR_RIDE) {
        return !R.paused;
    }
    return s_screen == SCR_DIAL || s_screen == SCR_NAV ||
           s_screen == SCR_GRADECAL || screen_is_setlist(s_screen);
}

static bool screen_has_lp2(void)
{
    /* 骑行：右键长按 = 暂停 / 继续（暂停后长按仍可继续，不能锁死）。
     * 设置列表：右键长按 = 确定。 */
    if (s_screen == SCR_RIDE) {
        return true;
    }
    return s_screen == SCR_DIAL || screen_is_setlist(s_screen);
}

static void do_short(int key);

static void lp_fire(void)
{
    lp_target_t target = LP.target;

    keylog("KEY%d long fired (target=%d) screen=%s", LP.key, (int)target,
           SCR_NAME[s_screen]);
    LP.active = false;
    switch (target) {
        case LP_ENTER:
            if (UD.unit != NULL) {
                lv_obj_remove_flag(UD.unit, LV_OBJ_FLAG_HIDDEN);
            }
            enter_selected_mode();
            break;
        case LP_ACTIVATE:
            setl_activate();
            break;
        case LP_PAUSE:
            if (!R.active) {
                ride_start();
                s_screen = SCR_RIDE;
                s_busy = false;
                rebuild();
            } else {
                R.paused = !R.paused;
                R.auto_paused = false;
                R.still_s = 0;
                if (R.paused) {
                    R.speed = 0.0;
                    R.cadence = 0;
                    R.power = 0;
                }
                s_busy = false;
                rebuild();
            }
            break;
        case LP_BACK:
            /* 骑行页左长按返回环形页：本次记录继续（不停表）。 */
            keylog("KEY%d long -> back (record continues)", LP.key);
            go_back();
            break;
        case LP_NAV_CTRL:
            if (s_nav_active) {
                s_sub_sel = 0;
                s_screen = SCR_NAV_LIVE;
            } else {
                s_screen = SCR_ELEVATION;
            }
            s_busy = false;
            rebuild();
            break;
        case LP_GRADE_ZERO:
            s_grade_off_x10 = -42;
            toast("坡度已归零");
            s_busy = false;
            rebuild();
            break;
        case LP_TOGGLE_RIDE:
            if (UD.unit != NULL) {
                lv_obj_remove_flag(UD.unit, LV_OBJ_FLAG_HIDDEN);
            }
            toggle_ride();
            if (s_screen == SCR_DIAL || s_screen == SCR_RIDE) {
                rebuild();
            }
            break;
        default:
            break;
    }
}

/* 长按不画进度条/弧：到 800 ms 直接执行（页面切换/弹窗本身就是明确结果）。 */
static void lp_tick(void)
{
    if (!LP.active) {
        return;
    }
    if (lv_tick_get() - LP.t0 >= LP.dur) {
        lp_fire();
    }
}

static void lp_begin(int key)
{
    LP.active = true;
    LP.key = key;
    LP.t0 = lv_tick_get();
    LP.dur = KEY_LONG_MS;
    if (key == 2 && s_screen == SCR_DIAL) {
        LP.target = LP_TOGGLE_RIDE;      /* 环形页右长 → 进入骑行 */
    } else if (key == 2 && s_screen == SCR_RIDE) {
        LP.target = LP_PAUSE;            /* 骑行页右长 → 暂停 */
    } else if (key == 1 && s_screen == SCR_DIAL) {
        LP.target = LP_ENTER;            /* 环形页左长 → 进入当前选项 */
    } else if (key == 1 && s_screen == SCR_RIDE) {
        LP.target = LP_BACK;             /* 骑行页左长 → 返回环形（记录继续） */
    } else if (screen_is_setlist(s_screen)) {
        LP.target = (key == 1) ? LP_BACK : LP_ACTIVATE;  /* ←长返回 / →长确定 */
    } else if (key == 1 && s_screen == SCR_NAV) {
        LP.target = LP_NAV_CTRL;
    } else if (key == 1 && s_screen == SCR_GRADECAL) {
        LP.target = LP_GRADE_ZERO;
    } else {
        LP.target = LP_ACTIVATE;
    }
}

/* 前向声明 */
static void rebuild(void);
static void go_back(void);

static void do_short(int key)
{
    /* 关机确认/进度由弹窗或 data_tick 管；这里不再处理。 */
    if (s_screen == SCR_SHUTDOWN) {
        return;
    }

    /* 设置列表：← 上移，→ 下移（长按见 lp_begin：左=返回，右=确定）。 */
    if (screen_is_setlist(s_screen)) {
        setl_move(key == 1 ? -1 : 1);
        return;
    }

    if (s_screen == SCR_RIDE) {
        if (R.active && R.paused) {
            if (key == 1) {
                keylog("KEY1 click (paused) -> back, record continues");
                go_back();
            } else {
                keylog("KEY2 click (paused) -> save?");
                s_modal = MODAL_SAVE_ASK;
                s_modal_key = 0;
                s_busy = false;
                rebuild();
            }
        } else {
            /* 骑行三页：← 上一页 / → 下一页（循环，不轮转自转）。 */
            s_ride_page = (s_ride_page + ((key == 2) ? 1 : 2)) % 3;
            keylog("KEY%d click -> ride page %d/%d", key, s_ride_page + 1, 3);
            s_busy = false;
            rebuild();
        }
        return;
    }

    if (s_screen == SCR_DIAL) {
        keylog("KEY%d click -> dial %s", key, key == 1 ? "CCW" : "CW");
        dial_rotate(key == 1 ? -1 : 1);
        return;
    }

    if (key == 1) {
        switch (s_screen) {
            case SCR_NAV:
                /* 导航页 KEY1 短：路线来源（GPX / 坐标点 / 常用点）；
                 * KEY1 长：导航中 → 本次导航；未导航 → 海拔详情。 */
                s_sub_sel = 0;
                s_screen = SCR_ROUTE_SRC;
                s_busy = false;
                rebuild();
                break;
            case SCR_RECORD:
                if (s_rec_sel + 1 < (s_rec_n < 4 ? s_rec_n : 4)) {
                    s_rec_sel++;
                    rec_sel_move(true);
                    rec_rows();
                }
                break;
            case SCR_ABOUT:
                s_about_sel = (s_about_sel + 1) % 5;
                about_focus_apply();
                break;
            default:
                break;
        }
    } else {
        go_back();
    }
}

/* ── 电源键（键盘 ↑）────────────────────────────────────────────────
 *
 *   单击（<400 ms）       无反应（只记日志；双击的第一次）
 *   双击（间隔 <300 ms）  熄屏（SCR_IDLE）
 *   长按（≥800 ms）       弹「确认关机？」（← 取消 / → 确认）
 *   熄屏 / 关机黑屏       按任意键或触摸唤醒；这一次输入不触发功能
 */
static struct {
    bool down;
    bool fired;
    bool consume_up;
    bool last_click_valid;
    bool dbl;
    uint32_t t0;
    uint32_t last_click;
} PWR;

static bool s_keylog;   /* SIM_HELM_KEYLOG=1：每次按键/动作打一行（取证用） */
static uint32_t s_sleep_t0;   /* 进入熄屏的时刻（振动唤醒用） */
static uint32_t s_vib_ms;     /* SIM_HELM_VIBRATE_MS：模拟“振动唤醒” */

static void keylog(const char *fmt, ...)
{
    va_list ap;

    if (!s_keylog) {
        return;
    }
    printf("helm-key[%u]: ", lv_tick_get());
    va_start(ap, fmt);
    vprintf(fmt, ap);
    va_end(ap);
    putchar('\n');
    fflush(stdout);
}

static void pwr_wake(void)
{

{
    if (s_screen == SCR_SHUTDOWN) {
        s_screen = SCR_DIAL;
        s_power_phase = 0;
        s_power_ticks = 0;
    } else {
        s_screen = s_idle_return;
    }
    s_idle_s = 0;
    s_busy = false;
    s_sleep_t0 = 0;
    rebuild();
}

static void pwr_sleep(void)
{
    if (s_screen == SCR_IDLE || s_screen == SCR_SHUTDOWN) {
        return;
    }
    s_idle_return = s_screen;
    s_idle_s = 0;
    s_screen = SCR_IDLE;
    s_busy = false;
    s_sleep_t0 = lv_tick_get();
    rebuild();
}

