static void ride_finish(void)
{
    char date[16];
    char sub[24];
    rec_t r;
    int hmax = 1;

    if (!R.active) {
        return;
    }
    R.active = false;
    R.paused = false;
    R.auto_paused = false;
    R.rec = false;
    R.still_s = 0;

    snprintf(date, sizeof(date), "10/29 周四");
    snprintf(sub, sizeof(sub), "%u:%02u · %.1f",
             (unsigned)(R.elapsed_s / 60), (unsigned)(R.elapsed_s % 60),
             R.avg);
    memset(&r, 0, sizeof(r));
    snprintf(r.date, sizeof(r.date), "%s", date);
    snprintf(r.sub, sizeof(r.sub), "%s", sub);
    r.dist = R.dist_km > 0.1 ? R.dist_km : 0.1;
    for (int i = 0; i < 5; i++) {
        if (R.hist[i] > hmax) {
            hmax = R.hist[i];
        }
    }
    for (int i = 0; i < 5; i++) {
        r.bars[i] = 10 + (R.hist[i] * 28) / hmax;
        if (r.bars[i] < 10) r.bars[i] = 10;
    }
    if (s_rec_n < (int)(sizeof(s_recs) / sizeof(s_recs[0]))) {
        s_rec_n++;
    }
    memmove(&s_recs[1], &s_recs[0],
            (size_t)(s_rec_n - 1) * sizeof(s_recs[0]));
    s_recs[0] = r;
    s_week[6] += r.dist;

    {
        char msg[64];

        snprintf(msg, sizeof(msg), "已保存 · %.1f %s · %u:%02u",
                 conv_dist(r.dist), unit_dist(),
                 (unsigned)(R.elapsed_s / 60), (unsigned)(R.elapsed_s % 60));
        toast(msg);
    }
}

