         * 否则无键可继续。 */
        if (R.paused) {
            R.paused = false;
            R.auto_paused = false;
            R.still_s = 0;
        }
        s_screen = SCR_RIDE;
        s_busy = false;
    } else {
        ride_start();
        s_screen = SCR_RIDE;
        s_busy = false;
    }
}

