static void go_back(void)
{
    switch (s_screen) {
        case SCR_IDLE:
            s_screen = s_idle_return;
            s_idle_s = 0;
            s_busy = false;
            rebuild();
            break;

        case SCR_DISPLAY:
        case SCR_UNITS:
        case SCR_NAV_SET:
        case SCR_SENSOR:
        case SCR_SENSOR_SCAN:
        case SCR_BLUETOOTH:
        case SCR_INBOX:
        case SCR_REC_SET:
        case SCR_POWER:
        case SCR_ABOUT:
        case SCR_USB:
            s_busy = true;
            s_tr_next = back_parent(s_screen);
            s_tr_post = POST_NONE;
            if (s_titlebar != NULL) {
                lv_obj_set_width(s_titlebar, 20);
                {
                    lv_anim_t a;

                    lv_anim_init(&a);
                    lv_anim_set_var(&a, s_titlebar);
                    lv_anim_set_values(&a, 20, 0);
                    lv_anim_set_duration(&a, 100);
                    lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
                    lv_anim_set_exec_cb(&a,
                                        (lv_anim_exec_xcb_t)lv_obj_set_width);
                    lv_anim_start(&a);
                }
            }
            {
                lv_anim_t a;

                lv_anim_init(&a);
                lv_anim_set_var(&a, &s_tr_p);
                lv_anim_set_values(&a, 0, 1000);
                lv_anim_set_duration(&a, 100);
                lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
                lv_anim_set_exec_cb(&a, tr_exec);
                lv_anim_set_ready_cb(&a, tr_done);
                s_tr_cy0 = DIAL_CY;
                s_tr_cy1 = DIAL_CY;
                s_tr_d0 = DIAL_D;
                s_tr_d1 = DIAL_D;
                s_tr_anim = lv_anim_start(&a);
            }
            break;

        case SCR_SHUTDOWN:
            if (s_power_phase == 2) {
                break;      /* 黑屏态只能按电源键“开机” */
            }
            s_screen = SCR_POWER;
            s_busy = false;
            rebuild();
