        case SCR_ROUTE_SRC:
        case SCR_NAV_LIVE:
        case SCR_GRADECAL:
            s_screen = (s_screen == SCR_GRADECAL) ? SCR_NAV_SET : SCR_NAV;
            s_busy = false;
            rebuild();
            break;

        case SCR_RIDE: {
            /* ANIMATION #4：hero 60ms 退出 → 硬切 → 环展开 120ms。 */
            s_busy = true;
            if (UR.hero_box != NULL) {
                lv_anim_t a;

                lv_anim_init(&a);
                lv_anim_set_var(&a, UR.hero_box);
                lv_anim_set_values(&a, 255, 0);
                lv_anim_set_duration(&a, 60);
                lv_anim_set_exec_cb(&a, hero_opa_exec);
                lv_anim_start(&a);
            }
            s_tr_next = SCR_DIAL;
            s_tr_post = POST_DIAL_FROM_RIDE;
            {
                lv_anim_t a;

                lv_anim_init(&a);
                lv_anim_set_var(&a, &s_tr_p);
                lv_anim_set_values(&a, 0, 1000);
                lv_anim_set_duration(&a, 60);
                lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
                lv_anim_set_exec_cb(&a, tr_exec);
                lv_anim_set_ready_cb(&a, tr_done);
                s_tr_cy0 = DIAL_CY;
                s_tr_cy1 = DIAL_CY;
                s_tr_d0 = DIAL_D;
                s_tr_d1 = DIAL_D;
                s_tr_anim = lv_anim_start(&a);
            }
            break;
        }

        case SCR_ELEVATION:
