static void setl_activate(void)
{
    const set_item_t *it;

    if (SL.sel < 0 || SL.sel >= SL.nrow) {
        return;
    }
    it = &SL.items[SL.item_of_row[SL.sel]];
    switch (it->act) {
        case SA_ENTER_DISPLAY: settings_enter(SCR_DISPLAY); return;
        case SA_ENTER_UNITS: settings_enter(SCR_UNITS); return;
        case SA_ENTER_NAVSET: settings_enter(SCR_NAV_SET); return;
        case SA_ENTER_SENSOR: settings_enter(SCR_SENSOR); return;
        case SA_ENTER_BLUETOOTH: settings_enter(SCR_BLUETOOTH); return;
        case SA_ENTER_RECSET: settings_enter(SCR_REC_SET); return;
        case SA_ENTER_POWER: settings_enter(SCR_POWER); return;
        case SA_ENTER_ABOUT: settings_enter(SCR_ABOUT); return;
        case SA_ENTER_GRADECAL: settings_enter(SCR_GRADECAL); return;
        case SA_ENTER_USB: settings_enter(SCR_USB); return;
        case SA_ENTER_INBOX: settings_enter(SCR_INBOX); return;
        case SA_ENTER_SCAN:
            s_sens_kind = it->extra % 3;
            s_sub_sel = 0;
            settings_to_sub(SCR_SENSOR_SCAN);
            return;
        case SA_CYCLE_BRIGHT:
            s_bright += 10;
            if (s_bright > 100) s_bright = 10;
            toast("亮度已调节");
            break;
        case SA_CYCLE_THEME:
            s_theme = (s_theme + 1) % 3;
            s_dark = (s_theme == 1);
            toast(s_theme == 0 ? "主题：浅色" : s_theme == 1 ? "主题：深色"
                                                             : "主题：自动");
            break;
        case SA_CYCLE_LOCK:

            s_screen = SCR_NAV;
            rebuild();
            break;

        case SCR_NAV:
        case SCR_RECORD:
            s_screen = SCR_DIAL;
            rebuild();
            dial_in(120, 120, 160);
            break;

        case SCR_SETTINGS:
            s_screen = SCR_DIAL;
            rebuild();
            dial_in(120, 120, 160);
            break;

        default:
            break;
    }
}

