static void rebuild(void)
{
    lv_obj_t *old = s_scr;

    /* 先停掉所有以「即将被删的对象」为变量的动画，避免 var 悬空。 */
    lv_anim_delete(&s_rot_p, NULL);
    lv_anim_delete(&s_tr_p, NULL);
    lv_anim_delete(&s_in_p, NULL);
    lv_anim_delete(&s_post_p, NULL);
    s_rot_anim = NULL;
    s_tr_anim = NULL;
    s_post_anim = NULL;
    if (UC.bar != NULL) lv_anim_delete(UC.bar, NULL);
    if (UA.titlebar != NULL) lv_anim_delete(UA.titlebar, NULL);
    for (int i = 0; i < SL.nrow; i++) {
        if (SL.bar[i] != NULL) lv_anim_delete(SL.bar[i], NULL);
    }
    if (s_titlebar != NULL) lv_anim_delete(s_titlebar, NULL);
    if (UR.hero_box != NULL) lv_anim_delete(UR.hero_box, NULL);
    LP.active = false;

    nav_stop();
    memset(&UD, 0, sizeof(UD));
    memset(&UR, 0, sizeof(UR));
    memset(&UN, 0, sizeof(UN));
    memset(&UC, 0, sizeof(UC));
    memset(&SL, 0, sizeof(SL));
    memset(&UA, 0, sizeof(UA));
    s_titlebar = NULL;
    s_hint = NULL;
    s_hint_bg = NULL;
    pts_reset();
    lv_obj_clean(old);

    switch (s_screen) {
        case SCR_RIDE: ride_build(); break;
        case SCR_NAV: nav_build(); break;
        case SCR_RECORD: rec_build(); break;
        case SCR_SETTINGS: set_build(); break;
        case SCR_DISPLAY: disp_build(); break;
        case SCR_UNITS: units_build(); break;
        case SCR_NAV_SET: navset_build(); break;
        case SCR_SENSOR: sens_build(); break;
        case SCR_SENSOR_SCAN: sensor_scan_build(); break;
        case SCR_BLUETOOTH: bt_build(); break;
        case SCR_INBOX: inbox_build(); break;
        case SCR_REC_SET: recset_build(); break;
        case SCR_POWER: power_build(); break;
        case SCR_GRADECAL: gradecal_build(); break;
        case SCR_USB: usb_build(); break;
        case SCR_ABOUT: about_build(); break;
        case SCR_IDLE: idle_build(); break;
        case SCR_SHUTDOWN: shutdown_build(); break;
        case SCR_ROUTE_SRC: routes_build(); break;
        case SCR_NAV_LIVE: navlive_build(); break;
        case SCR_ELEVATION: elev_build(); break;
        case SCR_ICONS: icons_build(false); break;
        case SCR_ICONS_DEMO: icons_build(true); break;
        case SCR_ICON_OPT: iconopt_build(); break;
        default: dial_build(); break;
    }
    if (s_toast_until != 0 && lv_tick_get() < s_toast_until) {
        hint_set(s_toast_msg);
    }
    modal_draw();       /* 模态弹窗永远画在最上层 */
    printf("helm: screen=%s mode=%d ride=%d page=%d\n", SCR_NAME[s_screen],
           s_mode, R.active ? 1 : 0, s_ride_page);
    fflush(stdout);
}

static void data_tick(lv_timer_t *t)
{
    (void)t;
    if (s_freeze) {
        return;
    }
    s_clock_tick++;
    if (s_clock_tick % 60 == 0) {
        s_min = (s_min + 1) % (24 * 60);
    }
    if (s_clock_tick % 120 == 0 && s_batt > 5) {
        s_batt--;
    }
    if (s_screen == SCR_DIAL || s_screen == SCR_RIDE) {
        statusbar_refresh();   /* 时间/电量/GPS 与状态栏同源 */
    }
    if (s_sens_search >= 0) {
        sensor_tick();
    }
    if (s_sens_connect_dev >= 0) {
        s_scan_ticks++;
        if (s_scan_ticks >= 2) {
            const int k = s_sens_kind;
            const int d = s_sens_connect_dev;

            s_sens_connect_dev = -1;
            s_sens_on[k] = true;
            s_sens_bars[k] = 4;
            snprintf(s_sens_dev[k], sizeof(s_sens_dev[0]), "%s",
                     SENS_NEARBY[k][d]);
            toast("已连接");
            if (s_screen == SCR_SENSOR_SCAN) {
                rebuild();
            }
        }
    }
